double torque(double rpm,double axial){ if(!std::isfinite(rpm)||!std::isfinite(axial))return NAN;
 int count=sizeof(rpm_grid)/sizeof(double);if(rpm<rpm_grid[0]||rpm>=rpm_grid[count-1])return 0;
 int i=0;while(rpm>=rpm_grid[i+1])i++;double f=(rpm-rpm_grid[i])/(rpm_grid[i+1]-rpm_grid[i]);double n=rpm/60.,j=std::clamp(std::max(axial,0.)/(n*.2286),0.,2.)*200.;int k=std::min(399,(int)j);double g=j-k;
 double a=cp_grid[i*401+k]*(1-g)+cp_grid[i*401+k+1]*g,b=cp_grid[(i+1)*401+k]*(1-g)+cp_grid[(i+1)*401+k+1]*g;
 return 1.225*n*n*pow(.2286,5)/(2*acos(-1.))*(a*(1-f)+b*f);
}
extern "C" int causal_replay(const double*initial,const double*controls,int n,double dt,int substeps,const double*p,double mass,const double*w,double voltage,double rpm_initial,double*out,double*rpmout){
 State y=Eigen::Map<const State>(initial);V wind=Eigen::Map<const V>(w);double h=dt/substeps,rpm=rpm_initial;
 for(int i=0;i<n;i++){
  Eigen::Map<State> dst(out+26*i);dst=y;rpmout[i]=rpm;if(!y.allFinite()||y.norm()>1e6)return i;
  for(int j=0;j<substeps && i<n-1;j++){
   const double*u=controls+3*i;double target=743.5778222336925*voltage*pow(std::max(u[0]-.0005141016498671315,0.),.9086807307118114);
   auto deriv=[&](const State& z,double t){double r=target+(rpm-target)*exp(-t/.01756125311487475);double v=(rot(z,0).transpose()*(z.segment<3>(7)-wind)).x();double input[3]={thrust(r,v)/p[18],u[1],u[2]};return rhs(z,input,p,mass,wind,r,(target-r)/.01756125311487475,torque(r,v));};
   State k1=deriv(y,0),k2=deriv(y+.5*h*k1,.5*h),k3=deriv(y+.5*h*k2,.5*h),k4=deriv(y+h*k3,h);y+=h/6*(k1+2*k2+2*k3+k4);y.segment<4>(3).normalize();y.segment<4>(16).normalize();rpm=target+(rpm-target)*exp(-h/.01756125311487475);
  }
 }return n;
}
extern "C" double mapped_thrust(double rpm,double axial){return thrust(rpm,axial);}


extern "C" double mapped_torque(double rpm,double axial){return torque(rpm,axial);}
